// ─── File: IdemTechniquesDemo.java ───
// Runnable demo of all four idempotency techniques.
package com.bank.idemtech;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class IdemTechniquesDemo {

    private static final Logger log = Logger.getLogger("IdemTech");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // 1) Idempotency key — payments
        PaymentService payments = new PaymentService();
        String r1 = payments.charge("K-PAY-1", "SAV2001", new BigDecimal("50000"));
        String r2 = payments.charge("K-PAY-1", "SAV2001", new BigDecimal("50000"));
        log.info(() -> "KEY  first=" + r1 + " retry=" + r2);

        // 2) Unique constraint — duplicate ledger rows
        LedgerLoader loader = new LedgerLoader();
        log.info(() -> "UNIQUE insert TXN-9: " + loader.insert("TXN-9"));
        log.info(() -> "UNIQUE insert TXN-9 again: " + loader.insert("TXN-9"));

        // 3) State-based validation — close account
        AccountService accounts = new AccountService();
        log.info(() -> "STATE close SAV2001: " + accounts.close("SAV2001"));
        log.info(() -> "STATE close SAV2001 again: " + accounts.close("SAV2001"));

        // 4) Distributed lock — one-time coupon under concurrency
        CouponService coupons = new CouponService();
        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<String> f1 = pool.submit(() -> coupons.redeem("DIWALI50", "SAV2001"));
        Future<String> f2 = pool.submit(() -> coupons.redeem("DIWALI50", "SAV2001"));
        log.info(() -> "LOCK redeem A=" + get(f1) + " B=" + get(f2));
        pool.shutdown();
    }

    static String get(Future<String> f) {
        try { return f.get(); } catch (Exception e) { return "err"; }
    }
}

// ─── key/PaymentService.java (idempotency key: store key→response) ───
class PaymentService {
    private final Map<String, String> keyToResponse = new ConcurrentHashMap<>();
    String charge(String idempotencyKey, String account, BigDecimal amount) {
        // Atomic claim: only the first caller computes; others get stored result.
        String existing = keyToResponse.get(idempotencyKey);
        if (existing != null) return existing + " (stored)";
        String response = "CHARGED " + account + " Rs." + amount
                + " txn=" + UUID.randomUUID().toString().substring(0, 8);
        keyToResponse.putIfAbsent(idempotencyKey, response);
        return keyToResponse.get(idempotencyKey);
    }
}

// ─── unique/LedgerLoader.java (unique constraint rejects duplicate) ───
class LedgerLoader {
    private final Set<String> references = ConcurrentHashMap.newKeySet();
    // add() returns false if the reference already exists → duplicate rejected.
    String insert(String reference) {
        boolean inserted = references.add(reference);   // simulates UNIQUE index
        return inserted ? "INSERTED" : "DUPLICATE REJECTED (already processed)";
    }
}

// ─── state/AccountService.java (skip if already in target state) ───
class AccountService {
    enum Status { ACTIVE, CLOSED }
    private final Map<String, Status> statuses = new ConcurrentHashMap<>();
    AccountService() { statuses.put("SAV2001", Status.ACTIVE); }
    // Conditional transition: no-op if already CLOSED (idempotent).
    String close(String id) {
        return statuses.merge(id, Status.CLOSED, (cur, tgt) -> cur) == Status.CLOSED
                && statuses.get(id) == Status.CLOSED
                ? transition(id) : "NO-OP";
    }
    private String transition(String id) {
        // Simpler explicit check for clarity:
        return "CLOSED (transition applied or already closed)";
    }
}

// ─── lock/CouponService.java (distributed lock: one winner) ───
class CouponService {
    private static final Logger log = Logger.getLogger("IdemTech");
    private final Map<String, Boolean> redeemed = new ConcurrentHashMap<>();
    private final Map<String, Object> locks = new ConcurrentHashMap<>();
    String redeem(String couponId, String account) {
        Object lock = locks.computeIfAbsent(couponId, k -> new Object());
        synchronized (lock) {   // simulates Redis SETNX lock across instances
            if (redeemed.putIfAbsent(couponId, Boolean.TRUE) != null) {
                return "ALREADY REDEEMED";
            }
            log.info(() -> "Coupon " + couponId + " redeemed by " + account);
            return "REDEEMED";
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
